 const native={css_zoom:'1',before_dpr:1,after_dpr:2,before_width:640,after_width:320,scroll_width:320};
 await test('native200-positive',()=>assertNativeZoom(native));
 for(const[name,mutate]of [['css-zoom',v=>v.css_zoom='2'],['overshoot225',v=>v.after_dpr=2.25],['no-reflow',v=>v.after_width=640],['overflow',v=>v.scroll_width=323]])await test(name+'-rejected',()=>{const v=clone(native);mutate(v);assert.throws(()=>assertNativeZoom(v));});
 const binding=JSON.parse(readFileSync('.artifacts/p05-v2-layout-producer-resume01/binding.json','utf8')),ack={root_run_ack:true,independent_producer_review:'PASS',independent_review_index_sha256:'a'.repeat(64),producer_runtime_digest:'b'.repeat(64),source_identity:binding.source_identity,image:binding.image};
 await test('binding-positive-inert',()=>assertBinding(binding,ack));
 for(const[name,mutate]of [['runACKfalse',v=>v.root_run_ack=false],['review-pending',v=>v.independent_producer_review='PENDING'],['wrong-source',v=>v.source_identity='c'.repeat(64)],['wrong-image',v=>v.image='sha256:'+'d'.repeat(64)],['missing-review-index',v=>v.independent_review_index_sha256=null]])await test(name+'-rejected',()=>{const v=clone(ack);mutate(v);assert.throws(()=>assertBinding(binding,v));});
 writeFileSync(join(dir,'a.mjs'),'one');const before=captureProducer(dir);
 await test('dynamic-file-positive',()=>assertUnchanged(before,captureProducer(dir)));
 await test('added-file-rejected',()=>{writeFileSync(join(dir,'added.mjs'),'new');assert.throws(()=>assertUnchanged(before,captureProducer(dir)));unlinkSync(join(dir,'added.mjs'));});
 await test('changed-file-rejected',()=>{writeFileSync(join(dir,'a.mjs'),'two');assert.throws(()=>assertUnchanged(before,captureProducer(dir)));writeFileSync(join(dir,'a.mjs'),'one');});
 await test('removed-file-rejected',()=>{unlinkSync(join(dir,'a.mjs'));assert.throws(()=>assertUnchanged(before,captureProducer(dir)));writeFileSync(join(dir,'a.mjs'),'one');});
 await test('runtime-digest-detects-code-name',()=>assert.notEqual(runtimeDigest(before),runtimeDigest({...before,'new.mjs':{type:'file',sha256:'x',bytes:1}})));
 await test('symlink-type-rejected',()=>{symlinkSync(join(dir,'a.mjs'),join(dir,'link.mjs'),'file');assert.throws(()=>captureProducer(dir));unlinkSync(join(dir,'link.mjs'));});
 await test('error-secrets-never-projected',()=>{assert.deepEqual(safeFailure(Error('cookie=SECRET private text')), {name:'Error',code:'ASSERTION_OR_OPERATION_FAILED'});assert.equal(safeFailure(Error('SCENE_PROJECTION_MISSING:private-sensitive')).code,'SCENE_PROJECTION_MISSING');});
 await test('PNG-signature-budget-positive',()=>{const file=join(dir,'ok.png');writeFileSync(file,Buffer.from('89504e470d0a1a0a','hex'));assert.equal(screenshotBudget().accept(file).bytes,8);});
 await test('non-PNG-rejected',()=>{const file=join(dir,'bad.png');writeFileSync(file,'notPNG');assert.throws(()=>screenshotBudget().accept(file));});
 await test('oversize-screenshot-rejected',()=>{const file=join(dir,'large.png');writeFileSync(file,Buffer.alloc(3*1024*1024+1));assert.throws(()=>screenshotBudget().accept(file));});
 // Execute the exact audit functions against declared inert DOM objects to exercise math and failure policy.
 const original=Object.fromEntries(['document','window','getComputedStyle','matchMedia','Node'].map(n=>[n,Object.getOwnPropertyDescriptor(globalThis,n)]));
 function dom(){
  const style={backgroundColor:'rgb(255, 255, 255)',backgroundImage:'none',opacity:'1',color:'rgb(0, 0, 0)',fontSize:'16px',fontWeight:'400',animationName:'none',animationDuration:'0s',transitionDuration:'0s',appearance:'none',borderTopWidth:'1px',borderTopColor:'rgb(0, 0, 0)',outlineWidth:'3px',outlineStyle:'solid',outlineColor:'rgb(0, 0, 0)',boxShadow:'none',zoom:'1',visibility:'visible',display:'block'};
  const make=(tag,id)=>({tagName:tag.toUpperCase(),id,style:{...style},parentElement:null,childNodes:[{nodeType:3,textContent:'synthetic'}],textContent:'synthetic',labels:[{textContent:'synthetic'}],getBoundingClientRect(){return {left:0,top:0,right:100,bottom:44,width:100,height:44};},getAttribute(n){return n==='data-testid'?id:null;},closest(){return null;},contains(e){return e===this;},matches(selector){if(selector===':focus-visible')return true;if(selector===':disabled')return false;return selector.toLowerCase().split(',').some(s=>s.trim().startsWith(tag));}});
  const root=make('html','root'),body=make('body','body'),button=make('button','game-stop');body.parentElement=root;button.parentElement=body;root.clientWidth=320;root.scrollWidth=320;const doc={body,documentElement:root,activeElement:button,scrollingElement:{scrollTop:0},querySelectorAll(){return [button];},getElementById(){return null;},elementFromPoint(){return button;}};
  Object.assign(globalThis,{document:doc,window:{innerWidth:320,innerHeight:568,devicePixelRatio:1},getComputedStyle:e=>e.style,matchMedia:()=>({matches:true}),Node:{TEXT_NODE:3}});return {root,body,button,doc,make};
 }
 try{
  await test('exact-DOM-audit-positive-inert',()=>{dom();assertObservation(domAudit());});
  await test('exact-DOM-low-text-contrast-rejected',()=>{const d=dom();d.button.style.color='rgb(190, 190, 190)';const a=domAudit();assert(a.contrast_failures>0);assert.throws(()=>assertObservation(a));});
  await test('exact-DOM-gradient-unresolved-rejected',()=>{const d=dom();d.body.style.backgroundImage='linear-gradient(white,black)';assert.throws(()=>assertObservation(domAudit()));});
  await test('exact-DOM-motion-rejected',()=>{const d=dom();d.button.style.transitionDuration='.2s';assert.throws(()=>assertObservation(domAudit()));});
  await test('exact-DOM-horizontal-overflow-rejected',()=>{const d=dom();d.root.scrollWidth=323;assert.throws(()=>assertObservation(domAudit()));});
  await test('exact-DOM-native-boundary-unresolved',()=>{const d=dom(),input=d.make('input','adult18');input.parentElement=d.body;input.style.appearance='auto';input.style.borderTopWidth='0px';d.doc.querySelectorAll=()=>[input];assert(domAudit().contrast_unresolved>0);});
  await test('exact-focus-positive-inert',()=>{dom();const r=focusAudit();assertKeyboard({controls:[r],truncated:false},['game-stop']);});
  await test('exact-focus-occlusion-rejected',()=>{const d=dom();d.doc.elementFromPoint=()=>({});const r=focusAudit();assert.throws(()=>assertKeyboard({controls:[r],truncated:false},['game-stop']));});
 }finally{for(const[name,descriptor]of Object.entries(original))if(descriptor)Object.defineProperty(globalThis,name,descriptor);else delete globalThis[name];}
 await test('actual-host-entrypoint-ACKfalse-no-allocation',()=>{const root=resolve('.artifacts/p05'),names=readdirSync(root).sort();const r=spawnSync(process.execPath,['.artifacts/p05-v2-layout-producer-resume01/run.mjs'],{encoding:'utf8',timeout:10000});assert.notEqual(r.status,0);assert(r.stderr.includes('ROOT_RUN_ACK_REQUIRED'));assert.deepEqual(readdirSync(root).sort(),names);});
}finally{assert.equal(dirname(resolve(dir)),resolve(tmpdir()));assert(resolve(dir).startsWith(join(resolve(tmpdir()),'venus-layout-inert-')));rmSync(dir,{recursive:true,force:true});}
console.log(JSON.stringify({scope:'AUTHOR_FINITE_INERT_ONLY_NO_BROWSER_NO_DOCKER',count:results.length,results},null,2));

/** Inert report-oracle controls. No browser, API, Docker or content activation. */
import assert from 'node:assert/strict';
import {expectedCells,expectedRoles,geometries,assertCell,assertMatrix} from './matrix.mjs';
const make=cell=>({...cell,status:'PASS',protocol:2,real_ui:true,reduced_motion:true,horizontal_overflow:false,hidden_scroll_trap:false,viewport:{...geometries.find(g=>g.id===cell.geometry),dpr:1,css_zoom:'1'},roles:expectedRoles(cell.scene).map(role=>({role,visible:true,focus_visible:true,keyboard_reached:true,focus_in_viewport:true,own_scope_matches:true,cross_private_leak:false,control_names_nonempty:true,contrast_failures:0,contrast_unresolved:0,normal_ui_clock:true,evidence_file:'synthetic-control.png'})),native_measurement:cell.native?{css_zoom:'1',before_dpr:1,after_dpr:2,before_width:640,after_width:320,x11_keyboard:true,isolated_browser:true,reset_verified:true}:null,native_role_measurements:cell.native?expectedRoles(cell.scene).map(role=>({role,css_zoom:'1',before_dpr:1,after_dpr:2,before_width:640,after_width:320,x11_keyboard:true,isolated_browser:true,reset_verified:true})):[],elapsed_ms:1,sweep_elapsed_ms:1,sweep_budget_ms:20000,clock_or_expiry_override:false});
const all=expectedCells().map(make),tests=[];
const test=(name,fn)=>{fn();tests.push({name,status:'PASS'});};
test('exact459-positive',()=>assert.equal(assertMatrix(all).cells,459));
test('counts360-normal45-native54-supplements',()=>{assert.equal(all.filter(r=>['entry','setup','public_questions','private_offer','private_active'].includes(r.scene)&&!r.native).length,360);assert.equal(all.filter(r=>['entry','setup','public_questions','private_offer','private_active'].includes(r.scene)&&r.native).length,45);assert.equal(all.filter(r=>['truth_dare_choice','yes_but_condition'].includes(r.scene)).length,54);});
test('one-engine-locale-is-not-full-pass',()=>assert.equal(assertMatrix(all.filter(r=>r.engine==='firefox'&&r.locale==='tr'),{engine:'firefox',locale:'tr'}).full_matrix,false));
test('missing-cell-rejected',()=>assert.throws(()=>assertMatrix(all.slice(1))));
test('duplicate-cell-rejected',()=>assert.throws(()=>assertMatrix([...all.slice(1),all[1]])));
for(const [name,change]of [
 ['P1-protocol',r=>r.protocol=1],['non-real-UI',r=>r.real_ui=false],['overflow',r=>r.horizontal_overflow=true],['hidden-scroll-trap',r=>r.hidden_scroll_trap=true],['wrong-role',r=>r.roles[0].role='host-guess'],['missing-keyboard',r=>r.roles[0].keyboard_reached=false],['hidden-focus',r=>r.roles[0].focus_visible=false],['focus-outside',r=>r.roles[0].focus_in_viewport=false],['stale-scope',r=>r.roles[0].own_scope_matches=false],['observer-private-leak',r=>r.roles[0].cross_private_leak=true],['contrast-unresolved',r=>r.roles[0].contrast_unresolved=1],['contrast-failure',r=>r.roles[0].contrast_failures=1],['motion',r=>r.reduced_motion=false],['sweep-expired',r=>r.sweep_elapsed_ms=r.sweep_budget_ms+1],['TTL-override',r=>r.clock_or_expiry_override=true],['wrong-width',r=>r.viewport.width++],['missing-screenshot',r=>r.roles[0].evidence_file='']
])test(name+'-rejected',()=>{const row=structuredClone(all[0]);change(row);assert.throws(()=>assertCell(row));});
const native=all.find(r=>r.native);
for(const[name,change]of [['CSS-zoom',r=>r.native_measurement.css_zoom='2'],['insufficient-native',r=>r.native_measurement.after_dpr=1.5],['overshoot225-is-not200',r=>r.native_measurement.after_dpr=2.25],['no-native-reflow',r=>r.native_measurement.after_width=640],['reset-failed',r=>r.native_measurement.reset_verified=false],['unisolated-native',r=>r.native_measurement.isolated_browser=false]])test(name+'-rejected',()=>{const row=structuredClone(native);change(row);assert.throws(()=>assertCell(row));});
console.log(JSON.stringify({scope:'INERT_CONTRACT_ONLY_NOT_BROWSER_EVIDENCE',tests,count:tests.length},null,2));

/** Execute exact host-runner AST in an inert VM with every Docker/filesystem call intercepted. */
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {resolve,join,dirname} from 'node:path';
import vm from 'node:vm';
import ts from 'typescript';
import {captureProducer,assertBinding,runtimeDigest,assertUnchanged,assertShard,sha} from './runner-policy.mjs';
import {inertShard} from './inert-report-fixture.mjs';
const root='.artifacts/p05-v2-layout-producer-resume01',source=readFileSync(root+'/run.mjs','utf8'),ast=ts.createSourceFile('run.mjs',source,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS);assert.equal(ast.parseDiagnostics.length,0);
let text=source;for(const node of [...ast.statements].reverse())if(ts.isImportDeclaration(node))text=text.slice(0,node.getFullStart())+text.slice(node.end);
const binding=JSON.parse(readFileSync(root+'/binding.json','utf8')),buildBytes=readFileSync(binding.root_build_receipt_path),results=[];
function replay(change={}){
 const project='venus-v2-layout-'+'01'.repeat(6),files=new Map(),fds=new Map(),commands=[],removals=[];let nextFd=10,sourceCaptures=0,producerCaptures=0;
 const producerBefore={'run.mjs':{type:'file',sha256:sha(Buffer.from(source)),bytes:Buffer.byteLength(source)},'binding.json':{type:'file',sha256:sha(Buffer.from(JSON.stringify(binding))),bytes:1}},ack={root_run_ack:true,independent_producer_review:'PASS',independent_review_index_sha256:'a'.repeat(64),source_identity:binding.source_identity,image:binding.image,producer_runtime_digest:runtimeDigest(producerBefore)},report=inertShard();change.ack?.(ack);change.report?.(report);
 const reportPath=resolve('.artifacts/p05/'+project+'/layout-report.json');files.set(reportPath,Buffer.from(JSON.stringify(report)));
 const review=Buffer.from(JSON.stringify({status:change.reviewFail?'FAIL':'PASS_LAYOUT_PRODUCER_METHOD_ONLY',source_identity:change.reviewSource?'f'.repeat(64):binding.source_identity}));ack.independent_review_path='.docs/implementation/reviews/p05/INERT/index.json';ack.independent_review_index_sha256=sha(review);if(change.reviewHash)ack.independent_review_index_sha256='f'.repeat(64);
 const read=path=>{path=String(path);if(path.endsWith('ROOT_RUN_ACK.json'))return Buffer.from(JSON.stringify(ack));if(path===ack.independent_review_path)return review;if(path.endsWith('binding.json'))return Buffer.from(JSON.stringify(binding));if(path===binding.root_build_receipt_path)return buildBytes;return files.get(path)??Buffer.from('INERT');};
 const write=(path,value)=>files.set(String(path),Buffer.from(value));
 const command=(exe,argv,options={})=>{
  assert.equal(exe,'docker');commands.push(argv);let status=0,stdout='',stderr='';
  if(argv[0]==='image')stdout=binding.image+'\n';
  else if(argv[0]==='container'&&argv[1]==='inspect'){if(change.liveWorker){stdout=JSON.stringify([{Config:{Labels:{'venus.p05.project':change.foreignWorker?'foreign':project,'venus.p05.role':'browser'}}}]);}else{status=1;stderr='No such container';}}
  else if(argv.includes('run')&&change.workerFail)status=1;
  else if(argv.includes('down')&&change.cleanupFail)status=1;
  else if(['ps','volume','network'].includes(argv[0])&&change.leftover===argv[0])stdout='inert-leftover';
  if(options.stdio?.[1]!==undefined){write(fds.get(options.stdio[1]),stdout+stderr);return {status};}return {status,stdout,stderr};
 };
 const inventory=()=>{const entries=Object.fromEntries(Array.from({length:1813},(_,i)=>['file'+i,'0'.repeat(64)]));sourceCaptures++;if(change.sourceChanged&&sourceCaptures>1)entries.file0='1'.repeat(64);return {files:entries,source_identity:binding.source_identity};};
 const ctx={assert,spawnSync:command,execFileSync:()=>JSON.stringify(inventory()),readFileSync:(path,encoding)=>encoding?read(path).toString('utf8'):read(path),writeFileSync:write,mkdtempSync:prefix=>prefix+'inert',mkdirSync:()=>{},rmSync:path=>removals.push(path),openSync:path=>{const fd=nextFd++;fds.set(fd,path);return fd;},closeSync:()=>{},copyFileSync:()=>{},resolve,join,dirname,tmpdir:()=>resolve('.artifacts/INERT-TMP'),randomBytes:n=>Buffer.alloc(n,1),sha,assertBinding,runtimeDigest,assertUnchanged,assertShard,captureProducer:()=>{producerCaptures++;const p=structuredClone(producerBefore);if(change.producerAdded&&producerCaptures>1)p['added.mjs']={type:'file',sha256:'f'.repeat(64),bytes:1};if(change.producerChanged&&producerCaptures>1)p['run.mjs'].sha256='e'.repeat(64);return p;},process:{env:{},platform:'win32',exitCode:0},console:{log:()=>{}},Buffer,JSON};
 let thrown=null;try{vm.runInNewContext(text,ctx,{timeout:10000});}catch(e){thrown=e;}
 const result=files.get(resolve('.artifacts/p05/'+project+'/runner.json'));
 return {thrown,result:result?JSON.parse(result):null,commands,removals,sourceCaptures,producerCaptures,exitCode:ctx.process.exitCode};
}
const test=(name,fn)=>{fn();results.push({name,status:'PASS'});};
test('baseline-inert-exact-runner-cleanup-pass',()=>{const r=replay();assert(!r.thrown);assert.equal(r.result.status,'PASS');assert.equal(r.result.cleanup,'PASS');assert.equal(r.sourceCaptures,2);assert.equal(r.producerCaptures,2);assert.equal(r.removals.length,1);});
test('ACKfalse-exits-before-any-Docker',()=>{const r=replay({ack:a=>a.root_run_ack=false});assert(r.thrown);assert.equal(r.commands.length,0);assert.equal(r.removals.length,0);});
test('unreviewed-producer-exits-before-Docker',()=>{const r=replay({ack:a=>a.independent_producer_review='PENDING'});assert(r.thrown);assert.equal(r.commands.length,0);});
test('wrong-runtime-digest-exits-before-Docker',()=>{const r=replay({ack:a=>a.producer_runtime_digest='b'.repeat(64)});assert(r.thrown);assert.equal(r.commands.length,0);});
for(const [name,change]of [['review-hash-mismatch',{reviewHash:true}],['review-verdict-fail',{reviewFail:true}],['review-source-mismatch',{reviewSource:true}]])test(name+'-before-Docker',()=>{const r=replay(change);assert(r.thrown);assert.equal(r.commands.length,0);});
for(const[name,change]of [
 ['added-producer-file',{producerAdded:true}],['changed-producer-bytes',{producerChanged:true}],['same-identity-different-full-source',{sourceChanged:true}],['worker-nonzero',{workerFail:true}],['cleanup-nonzero',{cleanupFail:true}],['leftover-container',{leftover:'ps'}],['leftover-volume',{leftover:'volume'}],['leftover-network',{leftover:'network'}],['forced-worker-removal',{liveWorker:true}],['missing-cell',{report:r=>r.records.pop()}],['missing-role',{report:r=>r.records[0].roles=[]}],['duplicate-cell',{report:r=>r.records[0]=r.records[1]}],['P1-protocol',{report:r=>r.records[0].protocol=1}],['CSS-native-claim',{report:r=>r.records.find(v=>v.native).native_measurement.css_zoom='2'}],['worker-cleanup-failed',{report:r=>r.cleanup='FAIL'}],['pageerror',{report:r=>r.page_errors.push({name:'Error'})}],['observer-truncation',{report:r=>r.request_metadata_overflow=true}],['fake-action-groups',{report:r=>r.keyboard_actions[0].scene='invented'}],['missing-action-receipt',{report:r=>r.keyboard_actions.find(a=>a.receipt_matches).receipt_matches=false}]
])test(name+'-FAIL',()=>{const r=replay(change);assert(!r.thrown);assert.equal(r.result.status,'FAIL');assert.equal(r.exitCode,1);});
test('foreign-worker-never-removed',()=>{const r=replay({liveWorker:true,foreignWorker:true});assert.equal(r.result.status,'FAIL');assert.equal(r.result.cleanup,'FAIL');assert(!r.commands.some(argv=>argv[0]==='container'&&argv[1]==='rm'));});
